attributes.text:
{
  "cases": [
    {
      "id": "TC-1",
      "title": "驗證 title 邊界長度 100 字元與 priority 邊界 1、5 時成功建立任務",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"a\" (100 characters), \"priority\": 1}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Valid Title\", \"priority\": 5}"
      ],
      "expected": "title 長度為 100 字元時應被接受（回傳 201 或 200）。priority 數值為 1 或 5 時應被接受。"
    },
    {
      "id": "TC-2",
      \"title": "驗證 title 超過 100 字元或為空白時回傳 422 錯誤",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project B\"}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"\" (empty)}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"a\" (101 characters)}"
      ],
      "expected": "title 長度超過 100 字元或為空白時應回傳 422 錯誤，且不得回傳 5xx。"
    },
    {
      "id": "TC-3",
      "title": "驗證 priority 數值為 0 或 6 以及超出範圍時回傳 422 錯誤",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project C\"}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task\", \"priority\": 0}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task\", \"priority\": 6}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task\", \"priority\": 99}"
      ],
      "expected": "priority 數值為 0 或 6（或超出範圍）時應回傳 422 錯誤。"
    },
    {
      "id": "TC-4",
      "title": "驗證更新 task 時 title 與 priority 的邊界與違規條件",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project D\"}",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Initial\"}",
        "PATCH /api/tasks/{tid} with {\"title\": \"\"}",
        "PATCH /api/tasks/{tid} with {\"priority\": 0}"
      ],
      "expected": "title 長度超過 100 字元或為空白時應回傳 422 錯誤，且不得回傳 5xx。priority 數值為 0 或 6（或超出範圍）時應回傳 422 錯誤。"
    }
  ]
}
